from Crypto.Util.number import long_to_bytes, bytes_to_long
from Crypto.Cipher import AES
from sage.all import factor

p = 179484242443842647076157545916813145863
g = p + 1
n = p ** 2

A = 8151835455168296616595830665780193016395220737150883049799789336683642356143
B = 646175581967890937758569249870803113107371238047129135444530422086013438685

msg1_hex = ''
msg2_hex = ''

msg1_bytes = bytes.fromhex(msg1_hex)
msg2_bytes = bytes.fromhex(msg2_hex)

a = A // p
b = B // p

shared_key = pow(A, b, n)
key_bytes = long_to_bytes(shared_key)

cipher = AES.new(key_bytes, AES.MODE_ECB)

msg1 = cipher.decrypt(msg1_bytes)
msg2 = cipher.decrypt(msg2_bytes)

print(f"{msg1.decode() = }")
print(f"{msg2.decode() = }")

