rsa_n = 757549557172637701705650564872978750202396193785959787958902702283992821805477951890673246862607
e = 65537
ct = 85819759671602122183683044089621006564060965146766513247725765468049327306596353146613780701836

phi = 1
for base, exponent in factor(rsa_n):
    phi *= (base - 1)

d = pow(e, -1, phi)
pt = pow(ct, d, rsa_n)

secret = long_to_bytes(pt).decode()
print(f"{secret = }")
